/*
 * The HTML that `reports/{id}/data.html` returns is a fragment written
 * against the old DHIS2 web front end: it expects jQuery, jQuery UI's
 * "redmond" theme, the legacy "light_blue" report theme and a handful of
 * global helper scripts to already be loaded on the page - none of which
 * this app ships. So rather than dropping the fragment into the iframe
 * as-is, it is wrapped in its own complete HTML document that pulls those
 * assets from the DHIS2 server directly. Matches the prototype's approach
 * (reports-app, prototype/redesign: standard-report-next/HtmlReportView.jsx
 * and standard-report/HtmlReportAssets.js), minus its resize-observer
 * height tracking.
 */

const CSS_FILES: Array<{ media: string; styleSheet: string }> = [
    {
        media: 'screen',
        styleSheet:
            '/dhis-web-commons/javascripts/jQuery/ui/css/redmond/jquery-ui.css',
    },
    {
        media: 'print',
        styleSheet: '/dhis-web-commons/css/print.css',
    },
    {
        media: 'screen,print',
        styleSheet: '/dhis-web-commons/css/themes/light_blue/light_blue.css',
    },
]

const SCRIPT_FILES: string[] = [
    '/dhis-web-commons/javascripts/jQuery/jquery.min.js',
    '/dhis-web-commons/javascripts/jQuery/jquery.utils.js',
    '/dhis-web-commons/javascripts/jQuery/ui/jquery-ui.min.js',
    '/dhis-web-commons/javascripts/dhis2/dhis2.util.js',
    '/dhis-web-commons/javascripts/dhis2/dhis2.period.js',
    '/dhis-web-commons/javascripts/commons.js',
    '/dhis-web-commons/javascripts/commons.ajax.js',
    '/dhis-web-commons/javascripts/lists.js',
    '/dhis-web-commons/javascripts/periodType.js',
    '/dhis-web-commons/javascripts/date.js',
    '/dhis-web-commons/oust/oust.js',
]

const PAGE_STYLES = `
    html {
        line-height: 1.15;
        text-size-adjust: 100%;
    }
    body {
        font-family: Roboto, sans-serif;
        box-sizing: inherit;
    }
    table {
        margin-top: 16px;
        border-collapse: collapse;
    }
    table td,
    table th {
        border: 1px solid #bcbcbc;
        padding: 4px;
    }
`

const createLinkTag = (
    baseUrl: string,
    { media, styleSheet }: { media: string; styleSheet: string }
) =>
    `<link type="text/css" rel="stylesheet" media="${media}" href="${baseUrl}${styleSheet}">`

const createScriptTag = (baseUrl: string, script: string) =>
    `<script src="${baseUrl}${script}" type="text/javascript"></script>`

export const wrapReportHtml = (baseUrl: string, html: string) => `
    <!DOCTYPE html>
    <html lang="en">
        <head>
            <meta charset="utf-8">
            ${CSS_FILES.map((file) => createLinkTag(baseUrl, file)).join('\n')}
            ${SCRIPT_FILES.map((script) =>
                createScriptTag(baseUrl, script)
            ).join('\n')}
            <style type="text/css">
                ${PAGE_STYLES}
            </style>
        </head>
        <body>
            ${html}
        </body>
    </html>
`
