import i18n from '@dhis2/d2-i18n'
import { FetchError } from '@dhis2/app-runtime'
import React, { useCallback, useState } from 'react'
import { Link } from 'react-router-dom'
import {
    Button,
    CircularLoader,
    DataTable,
    DataTableBody,
    DataTableCell,
    DataTableColumnHeader,
    DataTableHead,
    DataTableRow,
    DataTableFoot,
    DataTableSortDirection,
    Pagination,
    SharingDialog,
} from '@dhis2/ui'
import { useUserContext } from '../../../context'
import { DateValue, Warning } from '@/components'
import { RefetchReports } from '../useReports'
import { NoMatches } from './noMatches'
import { DeleteConfirmationModal } from './DeleteAction'
import styles from './reportsListManageView.module.css'
import { Pager } from '@/types/query'
import { Report, ReportItem } from '@/types/report'

const FullRowWrapper = ({ children }: { children: React.ReactNode }) => (
    <DataTableRow>
        <DataTableCell colSpan="3">{children}</DataTableCell>
    </DataTableRow>
)

/* The two sortable columns, each as its `iasc`/`idesc` order-param pair. */
const SORTABLE_COLUMNS = {
    displayName: ['displayName:iasc', 'displayName:idesc'],
    lastUpdated: ['lastUpdated:iasc', 'lastUpdated:idesc'],
} as const

type SortableColumn = keyof typeof SORTABLE_COLUMNS

const sortDirectionFor = (
    order: string,
    column: SortableColumn
): DataTableSortDirection => {
    const [ascOrder, descOrder] = SORTABLE_COLUMNS[column]
    if (order === ascOrder) {
        return 'asc'
    }
    if (order === descOrder) {
        return 'desc'
    }
    return 'default'
}

const toggledOrder = (order: string, column: SortableColumn) => {
    const [ascOrder, descOrder] = SORTABLE_COLUMNS[column]
    return order === ascOrder ? descOrder : ascOrder
}

const ReportsContents = ({
    loading,
    error,
    reports,
    searchTerm,
    setSharingModalOpenId,
    setDeleteModalOpen,
}: {
    loading: boolean
    error?: FetchError
    reports: Report[]
    searchTerm?: string
    setSharingModalOpenId: (id: string) => void
    setDeleteModalOpen: (params: { id: string; displayName: string }) => void
}) => {
    const { canAdd, canDelete } = useUserContext()
    if (loading) {
        return (
            <FullRowWrapper>
                <CircularLoader small />
            </FullRowWrapper>
        )
    }

    if (error) {
        return (
            <FullRowWrapper>
                <Warning
                    error={true}
                    title={i18n.t('Reports information is not accessible')}
                >
                    <span>
                        {i18n.t(
                            'There was a problem retrieving reports. Refresh the page to try again.'
                        )}
                    </span>
                </Warning>
            </FullRowWrapper>
        )
    }

    if (reports.length === 0) {
        return (
            <FullRowWrapper>
                {' '}
                <NoMatches searchTerm={searchTerm} />
            </FullRowWrapper>
        )
    }

    return reports.map((report) => {
        const access = report.access ?? {}
        const canEdit = canAdd && Boolean(access.update)
        const canShare = Boolean(access.update)
        const canDeleteReport = canDelete && Boolean(access.delete)

        return (
            <DataTableRow key={report.id}>
                <DataTableCell>{report.displayName}</DataTableCell>

                <DataTableCell>
                    <DateValue value={report.lastUpdated}></DateValue>
                </DataTableCell>

                <DataTableCell align="right">
                    <div className={styles.rowActions}>
                        <Link to={`/standardReports/view/${report.id}`}>
                            <Button small secondary>
                                {i18n.t('View')}
                            </Button>
                        </Link>
                        {canEdit && (
                            <Link to={`/standardReports/edit/${report.id}`}>
                                <Button small secondary>
                                    {i18n.t('Edit')}
                                </Button>
                            </Link>
                        )}
                        {canShare && (
                            <Button
                                small
                                secondary
                                onClick={() => {
                                    setSharingModalOpenId(report.id)
                                }}
                            >
                                {i18n.t('Share')}
                            </Button>
                        )}
                        {canDeleteReport && (
                            <Button
                                small
                                secondary
                                destructive
                                onClick={() => {
                                    setDeleteModalOpen({
                                        id: report?.id,
                                        displayName: report?.displayName,
                                    })
                                }}
                            >
                                {i18n.t('Delete')}
                            </Button>
                        )}
                    </div>
                </DataTableCell>
            </DataTableRow>
        )
    })
}

export const ReportsListManageView = ({
    reports,
    pager,
    loading,
    error,
    searchTerm,
    refetchReports,
    order,
    setOrder,
}: {
    reports: ReportItem[]
    pager: Pager
    loading: boolean
    error?: FetchError
    searchTerm: undefined | string
    refetchReports: RefetchReports
    order: string
    setOrder: (s: string) => void
}) => {
    const [sharingModalOpenId, setSharingModalOpenId] = useState<string | null>(
        null
    )
    const [deleteModalOpen, setDeleteModalOpen] = useState<{
        id: string
        displayName: string
    } | null>(null)
    const pageSize = pager?.pageSize
    const page = pager?.page
    const refetchAfterDelete = useCallback(() => {
        refetchReports({
            searchTerm,
            pageSize: pager?.pageSize,
            page: pager?.page,
        })
    }, [refetchReports, searchTerm, pageSize, page])
    return (
        <>
            {sharingModalOpenId && (
                <SharingDialog
                    type="report"
                    id={sharingModalOpenId}
                    onClose={() => setSharingModalOpenId(null)}
                />
            )}
            {deleteModalOpen && (
                <DeleteConfirmationModal
                    id={deleteModalOpen?.id}
                    displayName={deleteModalOpen?.displayName}
                    onClose={() => setDeleteModalOpen(null)}
                    refetchAfterDelete={refetchAfterDelete}
                />
            )}
            <div className={styles.manageTable}>
                <DataTable layout="fixed">
                    <DataTableHead>
                        <DataTableRow>
                            <DataTableColumnHeader
                                width="auto"
                                name="displayName"
                                sortDirection={sortDirectionFor(
                                    order,
                                    'displayName'
                                )}
                                onSortIconClick={() =>
                                    setOrder(toggledOrder(order, 'displayName'))
                                }
                            >
                                {i18n.t('Report')}
                            </DataTableColumnHeader>
                            <DataTableColumnHeader
                                width="140px"
                                name="lastUpdated"
                                sortDirection={sortDirectionFor(
                                    order,
                                    'lastUpdated'
                                )}
                                onSortIconClick={() =>
                                    setOrder(toggledOrder(order, 'lastUpdated'))
                                }
                            >
                                {i18n.t('Last changed')}
                            </DataTableColumnHeader>
                            <DataTableColumnHeader width="290px">
                                <span className={styles.visuallyHidden}>
                                    {i18n.t('Actions')}
                                </span>
                            </DataTableColumnHeader>
                        </DataTableRow>
                    </DataTableHead>

                    <DataTableBody>
                        <ReportsContents
                            reports={reports}
                            error={error}
                            loading={loading}
                            searchTerm={searchTerm}
                            setSharingModalOpenId={setSharingModalOpenId}
                            setDeleteModalOpen={setDeleteModalOpen}
                        />
                    </DataTableBody>

                    <DataTableFoot>
                        <FullRowWrapper>
                            <Pagination
                                {...pager}
                                onPageSizeChange={(v: number) => {
                                    refetchReports({
                                        searchTerm,
                                        pageSize: v,
                                        page: pager?.page,
                                    })
                                }}
                                onPageChange={(v: number) => {
                                    refetchReports({
                                        searchTerm,
                                        pageSize: pager?.pageSize,
                                        page: v,
                                    })
                                }}
                            />
                        </FullRowWrapper>
                    </DataTableFoot>
                </DataTable>
            </div>
        </>
    )
}
