import i18n from '@dhis2/d2-i18n'
import { SingleSelectFieldFF } from '@dhis2/ui'
import React from 'react'
import { Report } from '../types'
import { FLATTENED_RELATIVE_PERIODS } from './relativePeriodsDefinitions'
import { usePeriodField } from './usePeriodField'
import styles from './RelativePeriods.module.css'

export const RelativePeriodSelector = ({ report }: { report: Report }) => {
    const { modifiedInput, periodMeta } = usePeriodField()
    const reportPeriods = Object.entries(report.relativePeriods)
        .filter(([, value]) => value)
        .map(([key]) => key)

    const periodLabels = FLATTENED_RELATIVE_PERIODS.filter((p) =>
        reportPeriods.includes(p.value)
    )

    return (
        <SingleSelectFieldFF
            className={styles.fullWidthField}
            name="period"
            dataTest="standardReport-periodTypeSelector"
            label={i18n.t('Relative period')}
            options={periodLabels}
            input={modifiedInput}
            meta={periodMeta}
            required
            clearable
        />
    )
}
