import i18n from '@dhis2/d2-i18n'
import { useAlert, useDataMutation } from '@dhis2/app-runtime'
import React from 'react'
import {
    Modal,
    ModalTitle,
    ModalContent,
    ModalActions,
    NoticeBox,
    ButtonStrip,
    Button,
    CircularLoader,
} from '@dhis2/ui'
import styles from './DeleteAction.module.css'
import { ErrorReport } from '@/types/query'

const DELETE_MUTATION = {
    resource: 'reports',
    id: ({ id }: { id?: string }) => id,
    type: 'delete',
} as unknown as Parameters<typeof useDataMutation>[0]

export const DeleteConfirmationModal = ({
    id,
    displayName,
    onClose,
    refetchAfterDelete,
}: {
    id: string
    displayName: string
    onClose: () => void
    refetchAfterDelete: () => void
}) => {
    const { show: showDeletionSuccess } = useAlert(
        () =>
            i18n.t('Successfully deleted report "{{displayName}}"', {
                displayName: displayName,
            }),
        { success: true }
    )
    const [deleteMutation, { error, loading }] = useDataMutation(
        DELETE_MUTATION,
        {
            onComplete: () => {
                showDeletionSuccess()
                refetchAfterDelete()
                onClose()
            },
        }
    )

    const errorReports = error?.details?.response?.errorReports as
        | ErrorReport[]
        | undefined
    return (
        <Modal dataTest="delete-confirmation-modal" onClose={onClose}>
            <ModalTitle>
                {i18n.t(
                    'Are you sure that you want to delete "{{- displayName}}"?',
                    { displayName: displayName }
                )}
            </ModalTitle>

            {!!error && (
                <ModalContent>
                    <NoticeBox
                        error
                        title={i18n.t(
                            'Something went wrong deleting the report'
                        )}
                    >
                        <div>
                            {i18n.t(
                                'Failed to delete report "{{displayName}}"! {{messages}}',
                                {
                                    displayName: displayName,
                                }
                            )}
                        </div>

                        {!!errorReports?.length && (
                            <ul>
                                {errorReports.map(({ message }) => (
                                    <li key={message}>{message}</li>
                                ))}
                            </ul>
                        )}
                    </NoticeBox>
                </ModalContent>
            )}

            <ModalActions>
                <ButtonStrip>
                    <Button
                        disabled={loading}
                        destructive
                        onClick={() =>
                            deleteMutation({
                                id,
                                displayName: displayName,
                            })
                        }
                    >
                        {loading && (
                            <span className={styles.deleteButtonLoadingIcon}>
                                <CircularLoader extrasmall />
                            </span>
                        )}

                        {error ? i18n.t('Try again') : i18n.t('Delete')}
                    </Button>

                    <Button disabled={loading} onClick={onClose}>
                        {i18n.t('Cancel')}
                    </Button>
                </ButtonStrip>
            </ModalActions>
        </Modal>
    )
}
